import semver from 'semver';
export function majorOf(version) {
    return semver.parse(version.trim(), { loose: true })?.major;
}
export function satisfies(version, range) {
    const parsed = semver.parse(version.trim(), { loose: true });
    if (!parsed || semver.validRange(range, { loose: true }) === null)
        return undefined;
    return semver.satisfies(parsed, range, { loose: true });
}
